<?php function e($v){return esc((string)$v);} $skills=$data['skills']??[];$edu=$data['education']??[];$ach=$data['achievements']??[];$refs=$data['references']??[]; ?>
<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;background:#eee;font-family:"Times New Roman",serif;color:#111}.page{background:white;margin:auto;padding:11mm 12mm;font-size:11.5pt;line-height:1.12;min-height:<?= $paperSize==='long'?'13in':'297mm' ?>;width:<?= $paperSize==='long'?'8.5in':'210mm' ?>}.header{display:table;width:100%;border-bottom:2px solid #555;padding-bottom:8px}.headtext{display:table-cell;vertical-align:top}.photo{display:table-cell;width:33mm;height:33mm;text-align:right}.photo img{width:30mm;height:30mm;object-fit:cover;border:1px solid #555}.name{font-size:18pt;font-weight:bold;text-transform:uppercase}.section{margin-top:14px}.title{font-weight:bold;text-decoration:underline;font-size:12pt;margin-bottom:3px}.personal{border-collapse:collapse}.personal td:first-child{font-weight:bold;padding-right:14px}.item{margin:2px 0}.edu{margin:3px 0}.edu strong{display:block}.ref{display:table;width:100%;margin:4px 0;padding-left:18px}.refmain{display:table-cell}.refphone{display:table-cell;width:130px;font-weight:bold;text-align:right}.applicant{margin-top:18px}.applicant b{display:block;text-transform:uppercase}.muted{font-style:italic}</style></head><body><div class="page"><div class="header"><div class="headtext"><div class="name"><?=e($data['full_name']??'')?></div><div><?=e($data['street']??'')?></div><div><?=e($data['location']??'')?></div><div>Contact No.: <?=e($data['contact']??'')?></div><div>Email: <?=e($data['email']??'')?></div></div><div class="photo"><?php if(!empty($resume['photo_path']) && is_file(WRITEPATH.'uploads/resumes/'.$resume['photo_path'])):?><img src="<?= 'data:'.mime_content_type(WRITEPATH.'uploads/resumes/'.$resume['photo_path']).';base64,'.base64_encode(file_get_contents(WRITEPATH.'uploads/resumes/'.$resume['photo_path'])) ?>"><?php endif?></div></div><div class="section"><div class="title">PERSONAL DATA:</div><table class="personal"><tr><td>Date of Birth:</td><td><?=!empty($data['date_of_birth'])?date('F j, Y',strtotime($data['date_of_birth'])):''?></td></tr><tr><td>Citizenship:</td><td><?=e($data['citizenship']??'')?></td></tr><tr><td>Sex:</td><td><?=e($data['sex']??'')?></td></tr><tr><td>Civil Status:</td><td><?=e($data['civil_status']??'')?></td></tr><tr><td>Height:</td><td><?=e($data['height']??'')?></td></tr><tr><td>Weight:</td><td><?=e($data['weight']??'')?></td></tr><tr><td>Languages/Dialect Spoken:</td><td><?=e($data['languages']??'')?></td></tr></table></div><div class="section"><div class="title">SKILLS &amp; QUALIFICATIONS:</div><?php foreach($skills as $x): ?><?php if(trim((string)$x)!==''): ?><div class="item"><?=e($x)?></div><?php endif; ?><?php endforeach; ?></div><div class="section"><div class="title">EDUCATIONAL ATTAINMENT:</div><?php foreach($edu as $x):?><div class="edu"><strong><?=e($x['level']??'')?></strong><div><?=e($x['school']??'')?></div><div><?=e($x['address']??'')?></div><div><?=e($x['years']??'')?></div></div><?php endforeach?></div><div class="section"><div class="title">ACHIEVEMENT:</div><?php foreach($ach as $x): ?><?php if(trim((string)$x)!==''): ?><div class="item">• <?=e($x)?></div><?php endif; ?><?php endforeach; ?></div><div class="section"><div class="title">CHARACTER REFERENCES:</div><?php foreach($refs as $x):?><div class="ref"><div class="refmain">• &nbsp;<b><?=e($x['name']??'')?></b><div style="padding-left:16px"><?=e($x['position']??'')?></div><div style="padding-left:16px"><?=e($x['organization']??'')?></div></div><div class="refphone"><?=e($x['contact']??'')?></div></div><?php endforeach?></div><div class="applicant"><b><?=e($data['full_name']??'')?></b><span class="muted">Applicant</span></div></div></body></html>
